// nicht in das parallele Inject→Split→HTTP→Join-Muster der übrigen Konnektoren.
//
// Warum node:https statt fetch(): Der Function-Node läuft in einem eigenen
// vm-Kontext (Node-RED 4.1, 10-function.js: vm.createContext(sandbox)). Der
// Sandbox enthält console/util/Buffer/URL/Date/RED/setTimeout — die Node-Globals
// werden NICHT vererbt, fetch ist dort undefined. https und zlib kommen über die
// libs-Deklaration des Nodes herein; beides sind Kernmodule, also keine
// zusätzliche npm-Abhängigkeit im Image.
const BASIS = 'https://api.mobidata-bw.de/park-api/api/public/v3/parking-sites';
const PRO_SEITE = 500;
const MAX_SEITEN = 120;   // 31.909/500 ≈ 64 Seiten — Deckel mit Reserve fürs Wachstum
const PAUSE_MS = 1000;    // Höflichkeit gegenüber MobiData BW (wie die frühere 1-Anfrage/s-Node)

const schlaf = ms => new Promise(r => setTimeout(r, ms));
const holen = adresse => new Promise((erfuellen, ablehnen) => {
    const anfrage = https.get(adresse, {
        headers: {
            'Accept': 'application/json',
            'Accept-Encoding': 'gzip',
            'User-Agent': 'UDP Node-RED Konnektor parken-bw'
        }
    }, antwort => {
        const teile = [];
        antwort.on('data', d => teile.push(d));
        antwort.on('error', ablehnen);
        antwort.on('end', () => {
            try {
                const roh = Buffer.concat(teile);
                const kodierung = String(antwort.headers['content-encoding'] || '');
                erfuellen({
                    status: antwort.statusCode,
                    text: /gzip/i.test(kodierung) ? zlib.gunzipSync(roh).toString('utf8') : roh.toString('utf8')
                });
            } catch (e) { ablehnen(e); }
        });
    });
    anfrage.on('error', ablehnen);
    anfrage.setTimeout(30000, () => anfrage.destroy(new Error('Zeitüberschreitung nach 30 s')));
});

// Kompaktes Positionsarray statt Objekt — bei ~32.000 Anlagen zählt jedes Feld:
// 0 id · 1 lat · 2 lon · 3 Kapazität · 4 Zweck · 5 Name · 6 official_region_code
// 7 source_id · 8 original_uid · 9 modified_at · 10 Echtzeitdaten? · 11 freie Plätze (-1 = unbekannt)
// Apostroph bricht den TRoE-SQL-Insert (bekannter Orion-LD-Bug) -> ersetzen.
const putz = t => String(t == null ? '' : t).replace(/'/g, '’').slice(0, 80);

const gesehen = new Set();
const anlagen = [];
let start = null, seiten = 0, gesamt = null, fertig = false;
while (seiten < MAX_SEITEN) {
    const adresse = BASIS + '?limit=' + PRO_SEITE + (start === null ? '' : '&start=' + encodeURIComponent(start));
    let antwort;
    try {
        antwort = await holen(adresse);
    } catch (e) {
        node.error('ParkAPI: Seite ' + (seiten + 1) + ' nicht abrufbar (' + (e && e.message ? e.message : e) + ')');
        return null;
    }
    if (antwort.status !== 200) {
        node.error('ParkAPI: HTTP ' + antwort.status + ' auf Seite ' + (seiten + 1) + ' (' + adresse + ')');
        return null;
    }
    let seite;
    try { seite = JSON.parse(antwort.text); } catch (e) {
        node.error('ParkAPI: Seite ' + (seiten + 1) + ' ist kein gültiges JSON');
        return null;
    }
    if (!seite || !Array.isArray(seite.items)) {
        node.error('ParkAPI: Seite ' + (seiten + 1) + ' ohne items-Array — Antwortformat geändert?');
        return null;
    }
    seiten++;
    if (gesamt === null && typeof seite.total_count === 'number') gesamt = seite.total_count;

    // Überschneidungsprüfung. Genau dieser Fehler — Seiten, die alle denselben
    // Ausschnitt liefern — blieb einen Monat unentdeckt, weil er still war.
    // Lieber laut abbrechen als noch einmal 66× denselben Bestand schreiben.
    let doppelt = 0;
    for (const i of seite.items) if (gesehen.has(i.id)) doppelt++;
    if (doppelt) {
        node.error('ParkAPI: Seite ' + seiten + ' überschneidet die bisherigen Seiten in '
                   + doppelt + ' von ' + seite.items.length + ' Datensätzen — greift der Cursor »start« nicht mehr? Lauf abgebrochen');
        return null;
    }
    for (const i of seite.items) {
        gesehen.add(i.id);
        if (!i.lat || !i.lon) continue;
        if (i.purpose !== 'CAR' && i.purpose !== 'BIKE') continue;
        const echtzeit = i.has_realtime_data === true;
        anlagen.push([
            i.id, +i.lat, +i.lon, i.capacity || 0, i.purpose, putz((i.name || '').trim()),
            String(i.official_region_code == null ? '' : i.official_region_code),
            i.source_id == null ? null : i.source_id,
            i.original_uid == null ? '' : String(i.original_uid).slice(0, 64),
            i.modified_at || '',
            echtzeit,
            (echtzeit && i.realtime_free_capacity != null) ? i.realtime_free_capacity : -1
        ]);
    }
    node.status({ text: 'Seite ' + seiten + ' · ' + gesehen.size + (gesamt ? '/' + gesamt : '') + ' Datensätze' });

    if (seite.next_id === null || seite.next_id === undefined) { fertig = true; break; }
    if (String(seite.next_id) === String(start)) {
        node.error('ParkAPI: Cursor steht still (next_id ' + seite.next_id + ' wie zuvor) — Lauf abgebrochen');
        return null;
    }
    start = seite.next_id;
    await schlaf(PAUSE_MS);
}
// Niemals stillschweigend abschneiden: Wer den Deckel erreicht, bekommt einen
// Eintrag im Log — sonst wiederholt sich der Fehler von oben mit anderem Vorzeichen.
if (!fertig) {
    node.warn('ParkAPI: Seitendeckel ' + MAX_SEITEN + ' erreicht, Bestand unvollständig ('
              + gesehen.size + (gesamt ? ' von ' + gesamt : '') + ') — MAX_SEITEN anheben');
}
if (gesamt && fertig && gesehen.size < gesamt * 0.9) {
    node.warn('ParkAPI: nur ' + gesehen.size + ' von ' + gesamt + ' angekündigten Datensätzen geholt');
}
if (!anlagen.length) { node.warn('ParkAPI: keine verwertbaren Anlagen im Abzug'); return null; }
node.status({ text: seiten + ' Seiten · ' + gesehen.size + (gesamt ? '/' + gesamt : '') + ' Datensätze · ' + anlagen.length + ' verwertbar' });
msg.payload = anlagen;
msg.parkSeiten = seiten;
msg.parkGesamt = gesamt;
// Complete inventory: cursor ran to the end and delivered what it announced.
// Only then may the build step prune entities that are no longer in it.
msg.parkVollstaendig = fertig && !(gesamt && gesehen.size < gesamt * 0.9);
return msg;

// ParkAPI-Abzug -> ParkingSummary je Gemeinde + Einzelanlagen (Auto und Rad)

const GEM = global.get('bwGemeinden');
if (!Array.isArray(GEM)) { node.warn('bwGemeinden not in context yet — waiting for the master data flow'); return null; }
const GRZ = global.get('bwGrenzen') || null;
const GRZ_OK = !!GRZ && typeof GRZ === 'object' && Object.keys(GRZ).length > 0;
const GEMBYAGS = {};
for (const r of GEM) GEMBYAGS[r[0]] = r;

const PRUNE_OK = (() => {
    if (!Array.isArray(GEM)) return false;
    const prev = context.get('gemCount') || 0;
    if (GEM.length < 1000 || GEM.length < prev * 0.95) return false;
    context.set('gemCount', GEM.length);
    if (!GRZ || typeof GRZ !== 'object') return false;
    let covered = 0;
    for (const r of GEM) if (GRZ[r[0]] && Array.isArray(GRZ[r[0]].r)) covered++;
    return covered >= GEM.length * 0.99;
})();

const pip = (lat, lon, rings) => {
    for (const ring of rings) {
        let ins = false;
        for (let i = 0, j = ring.length - 1; i < ring.length; j = i++) {
            const xi = ring[i][0], yi = ring[i][1], xj = ring[j][0], yj = ring[j][1];
            if (((yi > lat) !== (yj > lat)) && (lon < (xj - xi) * (lat - yi) / (yj - yi) + xi)) ins = !ins;
        }
        if (ins) return true;
    }
    return false;
};
// Union of all polygon bounding boxes: cheap reject for points far outside BW
const BW_BOX = [180, 90, -180, -90];
for (const a in (GRZ || {})) {
    const b = GRZ[a].b;
    if (b[0] < BW_BOX[0]) BW_BOX[0] = b[0];
    if (b[1] < BW_BOX[1]) BW_BOX[1] = b[1];
    if (b[2] > BW_BOX[2]) BW_BOX[2] = b[2];
    if (b[3] > BW_BOX[3]) BW_BOX[3] = b[3];
}
const pipAgs = (lat, lon) => {
    for (const a in GRZ) {
        const g = GRZ[a], b = g.b;
        if (lon >= b[0] && lat >= b[1] && lon <= b[2] && lat <= b[3] && pip(lat, lon, g.r)) return a;
    }
    return null;
};
// AGS of the municipality containing the point, or null. No centroid fallback;
// sliver tolerance: see STRICT_LOOKUP in the generator.
const agsStrict = (lat, lon) => {
    if (!GRZ || typeof lat !== 'number' || typeof lon !== 'number' || !isFinite(lat) || !isFinite(lon)) return null;
    if (lon < BW_BOX[0] - 0.01 || lat < BW_BOX[1] - 0.01 || lon > BW_BOX[2] + 0.01 || lat > BW_BOX[3] + 0.01) return null;
    const hit = pipAgs(lat, lon);
    if (hit) return hit;
    const votes = {};
    let best = null;
    for (const [dy, dx] of [[0.003, 0], [-0.003, 0], [0, 0.0045], [0, -0.0045]]) {
        const a = pipAgs(lat + dy, lon + dx);
        if (!a) return null;
        votes[a] = (votes[a] || 0) + 1;
        if (!best || votes[a] > votes[best]) best = a;
    }
    return best;
};

const nearestStrict = (lat, lon) => { const a = agsStrict(lat, lon); return a ? (GEMBYAGS[a] || null) : null; };
const CTX = 'https://uri.etsi.org/ngsi-ld/v1/ngsi-ld-core-context-v1.6.jsonld';
const NOW = new Date().toISOString();
const P = (v, u) => ({ type: 'Property', value: v, unitCode: u, observedAt: NOW });

async function pruneStale(o) {
    const BASE = 'http://orion-ld:1026/ngsi-ld/v1/';
    const re = new RegExp(o.pattern);
    const ex = o.exclude ? new RegExp(o.exclude) : null;
    const frac = o.maxFraction || 0.3;
    const now = Date.now();
    const skip = (why, quiet) => {
        if (o.confirmKey) flow.set(o.confirmKey, {});   // "consecutive" means consecutive
        if (quiet) node.log(o.label + ': prune skipped, ' + why);
        else node.warn(o.label + ': prune skipped, ' + why);
        return 0;
    };
    if (o.intervalMs) {
        const key = 'pruneLastRun_' + o.label.replace(/[^A-Za-z0-9]+/g, '_');
        const prev = flow.get(key);
        flow.set(key, now);
        if (!prev || now - prev > 2.5 * o.intervalMs) return skip('no successful run within the last 2.5 intervals', !prev);
    }
    const req = (method, path, body) => new Promise((resolve, reject) => {
        const data = body ? Buffer.from(JSON.stringify(body)) : null;
        const headers = { 'Accept': 'application/json' };
        if (data) { headers['Content-Type'] = 'application/json'; headers['Content-Length'] = data.length; }
        const r = http.request(BASE + path, { method: method, headers: headers }, res => {
            const parts = [];
            res.on('data', d => parts.push(d));
            res.on('error', reject);
            res.on('end', () => resolve({ status: res.statusCode, headers: res.headers, text: Buffer.concat(parts).toString('utf8') }));
        });
        r.on('error', reject);
        r.setTimeout(30000, () => r.destroy(new Error('timeout after 30 s')));
        if (data) r.write(data);
        r.end();
    });
    const tsOf = e => {
        let t = 0;
        const see = v => { const x = Date.parse(v); if (isFinite(x) && x > t) t = x; };
        if (e.modifiedAt) see(e.modifiedAt);
        for (const k of Object.keys(e)) {
            const a = e[k];
            if (!a || typeof a !== 'object' || Array.isArray(a)) continue;
            if (a.observedAt) see(a.observedAt);
            if (a.modifiedAt) see(a.modifiedAt);
            if (k === 'dateObserved') see(a.value && typeof a.value === 'object' ? a.value['@value'] : a.value);
        }
        return t;
    };
    // 1. List all own entities, completely
    const PAGE = 1000, MAX_PAGES = 100;
    const existing = [];
    let total = null, done = false;
    try {
        for (let page = 0; page < MAX_PAGES; page++) {
            const res = await req('GET', 'entities?type=' + encodeURIComponent(o.type)
                + '&idPattern=' + encodeURIComponent(o.pattern)
                + '&attrs=' + encodeURIComponent(o.attrs || 'ags')
                + '&options=sysAttrs&count=true&limit=' + PAGE + '&offset=' + (page * PAGE));
            if (res.status !== 200) return skip('listing HTTP ' + res.status);
            const list = JSON.parse(res.text);
            if (!Array.isArray(list)) return skip('listing is not an array');
            if (total === null) total = parseInt(res.headers['ngsild-results-count'], 10);
            for (const e of list) existing.push(e);
            if (list.length < PAGE) { done = true; break; }
        }
    } catch (e) {
        return skip('listing failed (' + (e && e.message ? e.message : e) + ')');
    }
    if (!done || (isFinite(total) && existing.length < total)) {
        return skip('listing incomplete (' + existing.length + '/' + total + ')');
    }
    // 2. Candidates: own ids, not confirmed by this run, old enough
    let mine = 0, newest = 0;
    let cand = [];
    for (const e of existing) {
        if (!e || typeof e.id !== 'string' || !re.test(e.id)) continue;   // never touch foreign ids
        if (ex && ex.test(e.id)) continue;                                 // excluded sub-scheme
        if (o.accept && !o.accept(e.id, e)) continue;                      // extra ownership check
        mine++;
        const t = tsOf(e);
        if (t > newest) newest = t;
        if (o.keep && o.keep.has(e.id)) continue;
        if (o.graceMs && (!t || now - t < o.graceMs)) continue;
        cand.push(e.id);
    }
    // Result of a complete listing, for callers that act on it (o.listed)
    o.listed = { mine: mine, candidates: cand.length };
    if (o.liveMs && now - newest > o.liveMs) {
        return skip('no entity written within the last ' + Math.round(o.liveMs / 3600000) + ' h — connector down?');
    }
    const limit = Math.max(3, Math.floor(mine * frac));
    if (cand.length > limit) {
        return skip(cand.length + ' of ' + mine + ' entities would be deleted (limit ' + limit + ') — please check manually');
    }
    let confirm = null;
    if (o.confirmKey) {
        // { id: [first seen as candidate (ms), consecutive runs] }
        const prev = flow.get(o.confirmKey) || {};
        confirm = {};
        for (const id of cand) {
            const p = Array.isArray(prev[id]) ? prev[id] : [now, 0];
            confirm[id] = [p[0], p[1] + 1];
        }
        cand = cand.filter(id => confirm[id][1] >= 2 && now - confirm[id][0] >= (o.confirmMs || 24 * 3600e3));
        flow.set(o.confirmKey, confirm);
    }
    if (!cand.length) return 0;
    // 3. Delete in batches; count only what the broker confirms
    const deletedIds = [];
    for (let i = 0; i < cand.length; i += 100) {
        const chunk = cand.slice(i, i + 100);
        let res;
        try { res = await req('POST', 'entityOperations/delete', chunk); }
        catch (e) { node.warn(o.label + ': prune delete failed (' + (e && e.message ? e.message : e) + ')'); continue; }
        let ok = [];
        if (res.status === 204 || res.status === 200) ok = chunk;
        else if (res.status === 207) {
            try {
                const b = JSON.parse(res.text || '{}');
                const bad = new Set((b.errors || []).map(x => x && (x.entityId || x.id)));
                ok = Array.isArray(b.success) ? chunk.filter(id => b.success.includes(id))
                                              : chunk.filter(id => !bad.has(id));
            } catch (e) { ok = []; }
            if (ok.length < chunk.length) node.warn(o.label + ': prune delete, ' + (chunk.length - ok.length) + ' ids failed');
        } else node.warn(o.label + ': prune delete HTTP ' + res.status);
        for (const id of ok) deletedIds.push(id);
    }
    if (confirm) {
        for (const id of deletedIds) delete confirm[id];
        flow.set(o.confirmKey, confirm);
    }
    // Forget the change signatures of deleted entities, so a returning object
    // is written in full again instead of as a freshness-only update.
    if (o.sigKey && deletedIds.length) {
        const sig = flow.get(o.sigKey) || {};
        for (const id of deletedIds) delete sig[id];
        flow.set(o.sigKey, sig);
    }
    node.log(o.label + ': pruned ' + deletedIds.length + ' of ' + mine + ' entities');
    node.status({ text: (o.status ? o.status + ' · ' : '') + 'pruned ' + deletedIds.length + '/' + mine });
    return deletedIds.length;
}

// Pending change signatures: [flowKey, field, value, entityId]. A signature
// says "this value is in the broker". It must only take effect once the broker
// confirmed the write: the "commit signatures" node behind the upsert (see
// SIG_COMMIT in the generator) stores it for entities the broker accepted and
// drops it otherwise, so the entity is sent again in the next run. Storing it
// before the upsert froze entities for weeks whenever Orion-LD hung.
const pendingSigs = [];
function sigPending(key, field, value, id) { pendingSigs.push([key, field, value, id]); }
// Pending signatures of the given entities, for msg.sigCommit.
function sigsFor(entities) {
    if (!pendingSigs.length) return undefined;
    const ids = new Set(entities.map(e => e.id));
    const out = pendingSigs.filter(p => ids.has(p[3]));
    return out.length ? out : undefined;
}
// Entities in Batch-Chunks aufteilen (Orion-Payload-Limit)
function emitChunks(node, msg, entities, size) {
    const out = [];
    for (let i = 0; i < entities.length; i += size) {
        const chunk = entities.slice(i, i + size);
        out.push(Object.assign({}, msg, {
            payload: chunk,
            headers: { 'Content-Type': 'application/ld+json' },
            sigCommit: sigsFor(chunk),
            url: undefined,
            parts: undefined
        }));
    }
    return out;
}
// Stable per-entity rotation for freshness-only writes: with every = k, an
// unchanged entity refreshes its dateObserved in one of k consecutive runs
// (runs are periodMs apart), spreading the rows evenly over the runs.
function freshTurn(id, every, periodMs) {
    if (!every || every <= 1) return true;
    let h = 0;
    for (let i = 0; i < id.length; i++) h = (h * 31 + id.charCodeAt(i)) >>> 0;
    return (h + Math.floor(Date.now() / periodMs)) % every === 0;
}
// Änderungserkennung: Nur Entitäten mit geänderter Wertsignatur behalten. Orion-LD
// schreibt bei options=update je Attribut eine TRoE-Zeile — unabhängig davon, ob
// sich der Wert geändert hat. Ein über Stunden konstanter Pegel/Warnstatus/Median
// erzeugt so unnötig Volumen. sigOf(e) muss die Messwerte hashen, NICHT den
// dateObserved-Zeitstempel. Die Signaturen werden im flow-Kontext akkumuliert.
//
// opts.replace (Sprint 2.9): Standard ist MERGEN — Flows wie das GBFS-Carsharing
// rufen die Erkennung einmal je System auf und tragen jeweils nur einen
// Teilbestand bei; ein Ersetzen würde die Tabelle bei jedem System auf dessen
// Stationen eindampfen und die Erkennung wirkungslos machen. Für Flows, die den
// GANZEN Bestand in einem Lauf sehen (Parken landesweit), ist Mergen dagegen ein
// Leck: Entitäten, die aus der Quelle verschwinden, bleiben für immer in der
// Signaturtabelle stehen. Der flow-Kontext liegt über contextStorage
// (settings.js: localfilesystem) auch auf der Platte — das Leck wächst dort mit.
// Solche Aufrufer setzen { replace: true } und speichern nur den aktuellen Stand.
//
// Changed entities do not get their new signature here: the old one is removed
// and the new one is only pending (sigPending) until the commit node behind the
// upsert has seen the broker accept the write. A failed or hanging upsert thus
// leaves the entity "changed", and the next run sends it again.
// opts.freshEvery / opts.periodMs: refresh dateObserved of unchanged entities
// only in every k-th run (freshTurn) instead of every run.
function gateChanged(node, entities, key, sigOf, opts) {
    const ersetzen = !!(opts && opts.replace);
    const every = (opts && opts.freshEvery) || 1, period = (opts && opts.periodMs) || 3600e3;
    const prev = flow.get(key) || {};
    const table = ersetzen ? {} : prev;
    const out = [];
    let changed = 0;
    for (const e of entities) {
        const s = sigOf(e);
        if (prev[e.id] !== s) {
            delete table[e.id];
            sigPending(key, e.id, s, e.id);
            out.push(e); changed++;
            continue;
        }
        table[e.id] = s;
        if (e.dateObserved && freshTurn(e.id, every, period)) {
            // Unverändert: nur die Frische (dateObserved) auffrischen, NICHT die
            // vollen Messwerte. options=update ersetzt nur die mitgesendeten
            // Attribute — die Wert-Zeilen entfallen (Volumen gespart), aber
            // Healthcheck und Frontend sehen weiter, dass die Daten aktuell sind.
            out.push({ id: e.id, type: e.type, dateObserved: e.dateObserved, '@context': e['@context'] });
        }
    }
    flow.set(key, table);
    node.status({ text: changed + '/' + entities.length + ' geändert (Rest: nur Frische)' });
    return out;
}

const anlagen = Array.isArray(msg.payload) ? msg.payload.filter(Array.isArray) : [];
if (!anlagen.length) return null;

// Gemeindezuordnung über den Amtlichen Regionalschlüssel statt Punkt-in-Polygon:
// Die ParkAPI führt official_region_code zu 100 % — einen 12-stelligen ARS. Der
// AGS steckt darin, nur an anderer Stelle: AGS = ARS[0..5] + ARS[9..12]
// (Land+RB+Kreis, dann die Gemeinde; die Stellen 6–9 sind der Verbandsschlüssel).
// Beispiele: 081160019019 -> 08116019, 082120000000 -> 08212000. Gegen
// gui/public/bw-gemeinden.json geprüft: 830 von 830 Stichproben getroffen.
// Das ist exakt, kostet nichts und erspart diesem Konnektor die Suche in der
// 1 MB großen Grenzen-GeoJSON aus dem global-Kontext. The strict point-in-polygon
// lookup is only the fallback for records without or with an unknown ARS;
// without boundaries those records stay unassigned (no centroid guessing).
const arsZuAgs = ars => {
    const s = String(ars || '');
    return /^[0-9]{12}$/.test(s) ? s.slice(0, 5) + s.slice(9, 12) : null;
};

const byGem = {};
const radAnlagen = [];
const autoAnlagen = [];
let ueberArs = 0, ueberGeo = 0, ausserhalb = 0, ohneZuordnung = 0, frischeQuelle = 0;
const vorTagen = Date.now() - 86400000;
for (const a of anlagen) {
    const lat = a[1], lon = a[2];
    let g = null;
    const ags = arsZuAgs(a[6]);
    if (ags) {
        if (ags.slice(0, 2) !== '08') { ausserhalb++; continue; }   // ARS sagt: nicht Baden-Württemberg
        g = GEMBYAGS[ags] || null;
        if (g) ueberArs++;
    }
    if (!g) {
        if (!GRZ_OK) { ohneZuordnung++; continue; }
        g = nearestStrict(lat, lon);
        if (!g) { ausserhalb++; continue; }                          // in no BW municipality polygon
        ueberGeo++;
    }
    if (a[9] && Date.parse(a[9]) > vorTagen) frischeQuelle++;
    if (a[4] === 'BIKE') {
        // Nur Radanlagen mit Echtzeitbelegung — eine reine Kapazitätsangabe ohne
        // freie Plätze trüge im Dashboard nichts bei (B+R-Baustein »br«).
        if (a[11] >= 0) radAnlagen.push([g, a]);
        continue;
    }
    const b = byGem[g[0]] = byGem[g[0]] || { n: 0, cap: 0, rtFree: 0, rtN: 0 };
    b.n++; b.cap += a[3];
    if (a[11] >= 0) { b.rtFree += a[11]; b.rtN++; }
    autoAnlagen.push([g, a]);
}

// Kompakte Wertsignatur. Der flow-Kontext wird über contextStorage
// (settings.js: localfilesystem) auf die Platte geschrieben; bei ~26.000 Anlagen
// wären Rohsignaturen mehrere MB je Schreibvorgang. Zwei FNV-1a-Läufe mit
// verschiedenen Primzahlen ergeben 64 Bit, base36 kodiert ~13 Zeichen je Eintrag.
const hash64 = s => {
    let x = 0x811c9dc5, y = 0x1000193;
    for (let i = 0; i < s.length; i++) {
        const c = s.charCodeAt(i);
        x = Math.imul(x ^ c, 0x01000193) >>> 0;
        y = Math.imul(y ^ c, 0x85ebca6b) >>> 0;
    }
    return x.toString(36) + y.toString(36);
};

// Statik und Dynamik trennen. Orion-LD schreibt bei options=update je
// mitgesendetem Attribut eine TRoE-Zeile, unabhängig davon, ob sich der Wert
// geändert hat. Der frühere Stand schickte je Anlage und Lauf alle sieben
// Attribute; nur 4,7 % der Anlagen haben überhaupt Echtzeitdaten, die übrigen
// sechs Attribute ändern sich praktisch nie.
//
// Bewusst NICHT modified_at als Auslöser für den Vollschrieb: Das Feld wandert
// bei jedem Neueinlesen der Quelle mit. Im Abzug vom 24.08. trugen 93 von 500
// Datensätzen (darunter alle 32 mit Echtzeitdaten) ein frisches modified_at,
// ohne dass sich fachlich etwas geändert hätte — als Schreibgrund taugt es
// damit nicht, als Betriebsanzeige schon (siehe node.status unten). Maßgeblich
// ist die Wertsignatur der statischen Attribute, dieselbe Idee wie gateChanged().
const statik = flow.get('parkStatik') || {};
const belegung = flow.get('parkFrei') || {};
const neueStatik = {}, neueBelegung = {};
const entities = [];
const ids = new Set();
let voll = 0, nurFrei = 0, frisch = 0, unveraendert = 0;
const ANBIETER = 'MobiData BW ParkAPI';

// Stabile Entitäts-IDs aus der ParkAPI-eigenen id (»parkapi-<id>«). Vorher
// stand dort der geslugte Anlagenname, weshalb gleichnamige Anlagen aufeinander
// fielen (42× »hauptbahnhof-westseite«, 36× »list-gymnasium« …). Die AGS gehört
// bewusst NICHT in die ID: sie ist abgeleitet, und eine Neuverortung der Anlage
// würde die Entität samt Zeitreihe verwaisen lassen. Das Frontend fragt über das
// ags-ATTRIBUT ab (gui/public/smartcity-lib.js, byAgs), nie über die ID.
const anlegen = (typ, g, a) => {
    const kennung = 'urn:ngsi-ld:' + typ + ':parkapi-' + a[0];
    const lat = a[1], lon = a[2], kap = a[3], bez = a[5], frei = a[11];
    ids.add(kennung);
    const sig = hash64([g[0], bez, kap, lat.toFixed(5), lon.toFixed(5), a[7], a[8], a[4]].join('|'));
    // Signatures of written values only take effect after a confirmed upsert
    // (sigPending, commit node); unchanged ones are carried over directly.
    const dateObserved = { type: 'Property', value: { '@type': 'DateTime', '@value': NOW } };
    if (statik[kennung] !== sig) {
        // Erstsichtung oder echte Stammdatenänderung -> volle Entität
        voll++;
        sigPending('parkStatik', kennung, sig, kennung);
        if (frei >= 0) sigPending('parkFrei', kennung, frei, kennung);
        const e = {
            id: kennung,
            type: typ,
            ags: { type: 'Property', value: g[0] },
            name: { type: 'Property', value: bez || (typ === 'BikeParking' ? 'Radabstellanlage' : 'Parkplatz') },
            totalSpotNumber: { type: 'Property', value: kap, unitCode: 'C62' },
            dateObserved: dateObserved,
            dataProvider: { type: 'Property', value: ANBIETER },
            location: { type: 'GeoProperty', value: { type: 'Point', coordinates: [lon, lat] } },
            '@context': CTX
        };
        // Fremdschlüssel der Quelle mitschreiben: Sollte MobiData BW seine
        // Datenbank je neu aufbauen und die ids sich neu vergeben, lassen sich
        // die Entitäten darüber wieder zuordnen. Nur setzen, wenn vorhanden —
        // eine Property mit null-Wert nimmt Orion-LD nicht an.
        if (a[7] !== null && a[7] !== undefined) e.sourceId = { type: 'Property', value: a[7] };
        if (a[8]) e.originalUid = { type: 'Property', value: a[8] };
        if (typ === 'ParkingSite') e.category = { type: 'Property', value: 'CAR' };
        if (frei >= 0) e.availableSpotNumber = P(frei, 'C62');
        entities.push(e);
        return;
    }
    neueStatik[kennung] = sig;
    // Stammdaten unverändert: nur die Belegung, und nur wenn sie sich bewegt hat.
    // Freshness: sites with realtime occupancy refresh dateObserved in every run
    // (about 370 sites × 8 runs ≈ 3,000 rows/day), so views can tell a current
    // occupancy from a frozen one. Static-only sites (about 98 %) do not: their
    // data are master data without an observation time, and refreshing them
    // would cost about 200,000 rows/day. Their removal is handled by the prune.
    if (frei >= 0 && belegung[kennung] !== frei) {
        nurFrei++;
        sigPending('parkFrei', kennung, frei, kennung);
        entities.push({ id: kennung, type: typ, availableSpotNumber: P(frei, 'C62'), dateObserved: dateObserved, '@context': CTX });
        return;
    }
    if (frei >= 0) {
        neueBelegung[kennung] = frei;
        frisch++;
        entities.push({ id: kennung, type: typ, dateObserved: dateObserved, '@context': CTX });
    }
    unveraendert++;
};
for (const [g, a] of autoAnlagen) anlegen('ParkingSite', g, a);
for (const [g, a] of radAnlagen) anlegen('BikeParking', g, a);

// Ganzer Bestand je Lauf -> ersetzen statt mergen (sonst wächst die
// Signaturtabelle im flow-Kontext und damit auf der Platte unbegrenzt).
flow.set('parkStatik', neueStatik);
flow.set('parkFrei', neueBelegung);

// Kardinalitäts-Invariante: Wenn aus n Quelldatensätzen deutlich weniger als n
// Entitäts-IDs werden, kollidieren IDs — genau der Fehler, der hier einen Monat
// lang aus geslugten Namen entstand (500 Datensätze -> 336 IDs).
const quellsaetze = autoAnlagen.length + radAnlagen.length;
if (quellsaetze && ids.size / quellsaetze < 0.95) {
    node.warn('Parken-BW: nur ' + ids.size + ' verschiedene Entitäts-IDs aus ' + quellsaetze
              + ' Quelldatensätzen (' + Math.round(ids.size / quellsaetze * 100) + ' %) — ID-Kollision?');
}

const summen = Object.keys(byGem).map(ags => {
    const b = byGem[ags];
    const e = {
        id: 'urn:ngsi-ld:ParkingSummary:bw-' + ags,
        type: 'ParkingSummary',
        ags: { type: 'Property', value: ags },
        siteCount: P(b.n, 'C62'),
        totalCapacity: P(b.cap, 'C62'),
        '@context': CTX
    };
    if (b.rtN) {
        e.realtimeFree = P(b.rtFree, 'C62'); e.realtimeSites = P(b.rtN, 'C62');
        // Freshness of the realtime sum: gateChanged refreshes dateObserved of
        // unchanged sums (about 100 municipalities × 8 runs ≈ 800 rows/day).
        e.dateObserved = { type: 'Property', value: { '@type': 'DateTime', '@value': NOW } };
    }
    return e;
});
// Aggregate je Gemeinde: unverändert -> gar nicht schreiben. replace, weil dieser
// Lauf den kompletten Landesbestand sieht (siehe gateChanged).
for (const e of gateChanged(node, summen, 'parkSummenSig',
        x => [x.siteCount.value, x.totalCapacity.value,
              x.realtimeFree ? x.realtimeFree.value : '', x.realtimeSites ? x.realtimeSites.value : ''].join('|'),
        { replace: true })) entities.push(e);

const statusText = anlagen.length + ' Anlagen · ' + Object.keys(byGem).length + ' Gemeinden · '
              + voll + ' voll · ' + nurFrei + ' nur Belegung · ' + unveraendert + ' unverändert (' + frisch + ' Frische)'
              + ' · ' + frischeQuelle + ' mit frischem modified_at'
              + (ueberGeo ? ' · ' + ueberGeo + ' per Geo-Notnagel' : '')
              + (ausserhalb ? ' · ' + ausserhalb + ' außerhalb BW' : '')
              + (ohneZuordnung ? ' · ' + ohneZuordnung + ' ohne Zuordnung' : '');
node.status({ text: statusText });
// Prune sites and sums this complete run no longer contains (left the source,
// or outside BW and formerly assigned by centroid). Site timestamps are not
// refreshed on unchanged runs, so instead of a grace period an id must be
// missing in consecutive complete runs for at least 24 h (confirmKey); a
// bike site without realtime data for a few hours is not deleted.
if (msg.parkVollstaendig && PRUNE_OK && ids.size) {
    const summenIds = new Set(summen.map(e => e.id));
    (async () => {
        await pruneStale({ label: 'Parken-BW ParkingSite', type: 'ParkingSite',
                           pattern: '^urn:ngsi-ld:ParkingSite:parkapi-[^:]+$',
                           keep: ids, confirmKey: 'parkPruneSite', confirmMs: 24 * 3600e3,
                           intervalMs: 10800000, status: statusText });
        await pruneStale({ label: 'Parken-BW BikeParking', type: 'BikeParking',
                           pattern: '^urn:ngsi-ld:BikeParking:parkapi-[^:]+$',
                           keep: ids, confirmKey: 'parkPruneBike', confirmMs: 24 * 3600e3,
                           intervalMs: 10800000, status: statusText });
        await pruneStale({ label: 'Parken-BW ParkingSummary', type: 'ParkingSummary',
                           pattern: '^urn:ngsi-ld:ParkingSummary:bw-[0-9]{8}$',
                           keep: summenIds, confirmKey: 'parkPruneSummary', confirmMs: 24 * 3600e3,
                           intervalMs: 10800000, status: statusText });
        // One-off cleanup of the legacy id scheme. Until August 2026 the ids
        // were <municipality slug>-<slugged name or lat-lon>; nothing writes
        // them any more (a static test forbids ParkingSite/BikeParking ids other
        // than parkapi-<id> in every flow), so the share limit cannot apply:
        // none of them is ever confirmed again. Instead:
        //   * own pattern: [a-z0-9.-] only, the current parkapi- scheme is
        //     excluded, the id must start with a known municipality slug AND
        //     the entity must carry this connector's dataProvider (municipal
        //     B+R connectors use the same slug-prefixed id style, see
        //     docs/staedte-hinzufuegen.md, and must never be touched);
        //   * untouched for 7 days (modifiedAt / observedAt / dateObserved;
        //     an entity without timestamp is kept);
        //   * only after a complete inventory run with plausible master data;
        //   * at most once a day, and only if the previous daily check was
        //     done (interval check), so a single snapshot never deletes.
        // Once the legacy entities are gone, the daily check lists nothing.
        //   * created before the switch to parkapi- ids (createdAt, system
        //     attribute; commit of 25.08.2026 03:28 CEST), so nothing written
        //     since can ever match;
        //   * once a complete listing finds no legacy entity of either type
        //     any more, the check switches itself off (parkLegacyDone).
        if (!flow.get('parkLegacyDone') && Date.now() - (flow.get('parkLegacyLast') || 0) >= 20 * 3600e3) {
            flow.set('parkLegacyLast', Date.now());
            const SLUGS = new Set(GEM.map(r => r[8]).filter(Boolean));
            const legacyOwn = id => {
                const parts = id.split(':').slice(3).join(':').split('-');
                for (let i = 1; i < parts.length; i++) if (SLUGS.has(parts.slice(0, i).join('-'))) return true;
                return false;
            };
            const MIGRATION = Date.parse('2026-08-25T01:28:11Z');
            const legacyParkApi = (id, e) => legacyOwn(id) && !!e && !!e.dataProvider && e.dataProvider.value === ANBIETER
                && Date.parse(e.createdAt) < MIGRATION;
            const legacy = typ => ({ label: 'Parken-BW legacy ' + typ, type: typ,
                pattern: '^urn:ngsi-ld:' + typ + ':[a-z0-9][a-z0-9.-]*$',
                attrs: 'ags,dataProvider', exclude: '^urn:ngsi-ld:' + typ + ':parkapi-', accept: legacyParkApi,
                keep: ids, graceMs: 7 * 24 * 3600e3, maxFraction: 1,
                intervalMs: 86400000, status: statusText });
            const legacySite = legacy('ParkingSite'), legacyBike = legacy('BikeParking');
            await pruneStale(legacySite);
            await pruneStale(legacyBike);
            if (legacySite.listed && legacyBike.listed && !legacySite.listed.mine && !legacyBike.listed.mine) {
                flow.set('parkLegacyDone', true);
                node.log('Parken-BW: no legacy parking ids left, cleanup switched off');
            }
        }
    })().catch(e => node.warn('Parken-BW: prune failed (' + (e && e.message ? e.message : e) + ')'));
} else {
    // Incomplete run: candidates must be missing in CONSECUTIVE complete runs
    for (const k of ['parkPruneSite', 'parkPruneBike', 'parkPruneSummary']) flow.set(k, {});
}
if (!entities.length) return null;
return [emitChunks(node, msg, entities, 100)];

// Commit pending change signatures (msg.sigCommit) for confirmed entities only
const sc = msg.sigCommit;
delete msg.sigCommit;
if (!Array.isArray(sc) || !sc.length) return msg;
const st = msg.statusCode;
let ok = null;   // null = nothing confirmed, true = whole batch, Set = these ids
if (st === 207) {
    // Multi-status: per entity. "success" lists the confirmed ids; without it,
    // everything not listed in "errors" counts. Unreadable body: nothing.
    try {
        const b = typeof msg.payload === 'string' ? JSON.parse(msg.payload || '{}') : (msg.payload || {});
        const idOf = x => typeof x === 'string' ? x : (x && (x.entityId || x.id));
        if (Array.isArray(b.success)) ok = new Set(b.success.map(idOf));
        else if (Array.isArray(b.errors)) {
            const bad = new Set(b.errors.map(idOf));
            ok = new Set(sc.map(p => p[3]).filter(id => !bad.has(id)));
        }
    } catch (e) { ok = null; }
} else if (typeof st === 'number' && st >= 200 && st < 300) ok = true;
const tables = {};
let kept = 0, dropped = 0;
for (const [key, field, value, id] of sc) {
    if (ok !== true && !(ok && ok.has(id))) { dropped++; continue; }
    const t = tables[key] = tables[key] || flow.get(key) || {};
    if (value === null) delete t[field]; else t[field] = value;
    kept++;
}
for (const key of Object.keys(tables)) flow.set(key, tables[key]);
if (dropped) {
    node.warn('Upsert not confirmed (' + st + '): ' + dropped + ' change signatures dropped, entities will be sent again'
              + (typeof msg.payload === 'string' ? ' — ' + msg.payload.slice(0, 200) : ''));
}
node.status({ fill: dropped ? 'yellow' : 'green', shape: 'dot', text: kept + ' committed' + (dropped ? ', ' + dropped + ' dropped' : '') + ' (' + st + ')' });
return msg;

// GBFS-Systemliste -> je System eine free_bike_status-Abfrage
if (msg.statusCode >= 400 || !msg.payload || !Array.isArray(msg.payload.systems)) {
    node.warn('GBFS-BW: Systemliste nicht ladbar');
    return null;
}

async function pruneStale(o) {
    const BASE = 'http://orion-ld:1026/ngsi-ld/v1/';
    const re = new RegExp(o.pattern);
    const ex = o.exclude ? new RegExp(o.exclude) : null;
    const frac = o.maxFraction || 0.3;
    const now = Date.now();
    const skip = (why, quiet) => {
        if (o.confirmKey) flow.set(o.confirmKey, {});   // "consecutive" means consecutive
        if (quiet) node.log(o.label + ': prune skipped, ' + why);
        else node.warn(o.label + ': prune skipped, ' + why);
        return 0;
    };
    if (o.intervalMs) {
        const key = 'pruneLastRun_' + o.label.replace(/[^A-Za-z0-9]+/g, '_');
        const prev = flow.get(key);
        flow.set(key, now);
        if (!prev || now - prev > 2.5 * o.intervalMs) return skip('no successful run within the last 2.5 intervals', !prev);
    }
    const req = (method, path, body) => new Promise((resolve, reject) => {
        const data = body ? Buffer.from(JSON.stringify(body)) : null;
        const headers = { 'Accept': 'application/json' };
        if (data) { headers['Content-Type'] = 'application/json'; headers['Content-Length'] = data.length; }
        const r = http.request(BASE + path, { method: method, headers: headers }, res => {
            const parts = [];
            res.on('data', d => parts.push(d));
            res.on('error', reject);
            res.on('end', () => resolve({ status: res.statusCode, headers: res.headers, text: Buffer.concat(parts).toString('utf8') }));
        });
        r.on('error', reject);
        r.setTimeout(30000, () => r.destroy(new Error('timeout after 30 s')));
        if (data) r.write(data);
        r.end();
    });
    const tsOf = e => {
        let t = 0;
        const see = v => { const x = Date.parse(v); if (isFinite(x) && x > t) t = x; };
        if (e.modifiedAt) see(e.modifiedAt);
        for (const k of Object.keys(e)) {
            const a = e[k];
            if (!a || typeof a !== 'object' || Array.isArray(a)) continue;
            if (a.observedAt) see(a.observedAt);
            if (a.modifiedAt) see(a.modifiedAt);
            if (k === 'dateObserved') see(a.value && typeof a.value === 'object' ? a.value['@value'] : a.value);
        }
        return t;
    };
    // 1. List all own entities, completely
    const PAGE = 1000, MAX_PAGES = 100;
    const existing = [];
    let total = null, done = false;
    try {
        for (let page = 0; page < MAX_PAGES; page++) {
            const res = await req('GET', 'entities?type=' + encodeURIComponent(o.type)
                + '&idPattern=' + encodeURIComponent(o.pattern)
                + '&attrs=' + encodeURIComponent(o.attrs || 'ags')
                + '&options=sysAttrs&count=true&limit=' + PAGE + '&offset=' + (page * PAGE));
            if (res.status !== 200) return skip('listing HTTP ' + res.status);
            const list = JSON.parse(res.text);
            if (!Array.isArray(list)) return skip('listing is not an array');
            if (total === null) total = parseInt(res.headers['ngsild-results-count'], 10);
            for (const e of list) existing.push(e);
            if (list.length < PAGE) { done = true; break; }
        }
    } catch (e) {
        return skip('listing failed (' + (e && e.message ? e.message : e) + ')');
    }
    if (!done || (isFinite(total) && existing.length < total)) {
        return skip('listing incomplete (' + existing.length + '/' + total + ')');
    }
    // 2. Candidates: own ids, not confirmed by this run, old enough
    let mine = 0, newest = 0;
    let cand = [];
    for (const e of existing) {
        if (!e || typeof e.id !== 'string' || !re.test(e.id)) continue;   // never touch foreign ids
        if (ex && ex.test(e.id)) continue;                                 // excluded sub-scheme
        if (o.accept && !o.accept(e.id, e)) continue;                      // extra ownership check
        mine++;
        const t = tsOf(e);
        if (t > newest) newest = t;
        if (o.keep && o.keep.has(e.id)) continue;
        if (o.graceMs && (!t || now - t < o.graceMs)) continue;
        cand.push(e.id);
    }
    // Result of a complete listing, for callers that act on it (o.listed)
    o.listed = { mine: mine, candidates: cand.length };
    if (o.liveMs && now - newest > o.liveMs) {
        return skip('no entity written within the last ' + Math.round(o.liveMs / 3600000) + ' h — connector down?');
    }
    const limit = Math.max(3, Math.floor(mine * frac));
    if (cand.length > limit) {
        return skip(cand.length + ' of ' + mine + ' entities would be deleted (limit ' + limit + ') — please check manually');
    }
    let confirm = null;
    if (o.confirmKey) {
        // { id: [first seen as candidate (ms), consecutive runs] }
        const prev = flow.get(o.confirmKey) || {};
        confirm = {};
        for (const id of cand) {
            const p = Array.isArray(prev[id]) ? prev[id] : [now, 0];
            confirm[id] = [p[0], p[1] + 1];
        }
        cand = cand.filter(id => confirm[id][1] >= 2 && now - confirm[id][0] >= (o.confirmMs || 24 * 3600e3));
        flow.set(o.confirmKey, confirm);
    }
    if (!cand.length) return 0;
    // 3. Delete in batches; count only what the broker confirms
    const deletedIds = [];
    for (let i = 0; i < cand.length; i += 100) {
        const chunk = cand.slice(i, i + 100);
        let res;
        try { res = await req('POST', 'entityOperations/delete', chunk); }
        catch (e) { node.warn(o.label + ': prune delete failed (' + (e && e.message ? e.message : e) + ')'); continue; }
        let ok = [];
        if (res.status === 204 || res.status === 200) ok = chunk;
        else if (res.status === 207) {
            try {
                const b = JSON.parse(res.text || '{}');
                const bad = new Set((b.errors || []).map(x => x && (x.entityId || x.id)));
                ok = Array.isArray(b.success) ? chunk.filter(id => b.success.includes(id))
                                              : chunk.filter(id => !bad.has(id));
            } catch (e) { ok = []; }
            if (ok.length < chunk.length) node.warn(o.label + ': prune delete, ' + (chunk.length - ok.length) + ' ids failed');
        } else node.warn(o.label + ': prune delete HTTP ' + res.status);
        for (const id of ok) deletedIds.push(id);
    }
    if (confirm) {
        for (const id of deletedIds) delete confirm[id];
        flow.set(o.confirmKey, confirm);
    }
    // Forget the change signatures of deleted entities, so a returning object
    // is written in full again instead of as a freshness-only update.
    if (o.sigKey && deletedIds.length) {
        const sig = flow.get(o.sigKey) || {};
        for (const id of deletedIds) delete sig[id];
        flow.set(o.sigKey, sig);
    }
    node.log(o.label + ': pruned ' + deletedIds.length + ' of ' + mine + ' entities');
    node.status({ text: (o.status ? o.status + ' · ' : '') + 'pruned ' + deletedIds.length + '/' + mine });
    return deletedIds.length;
}

const GEM = global.get('bwGemeinden');
const GRZ = global.get('bwGrenzen') || null;

const PRUNE_OK = (() => {
    if (!Array.isArray(GEM)) return false;
    const prev = context.get('gemCount') || 0;
    if (GEM.length < 1000 || GEM.length < prev * 0.95) return false;
    context.set('gemCount', GEM.length);
    if (!GRZ || typeof GRZ !== 'object') return false;
    let covered = 0;
    for (const r of GEM) if (GRZ[r[0]] && Array.isArray(GRZ[r[0]].r)) covered++;
    return covered >= GEM.length * 0.99;
})();

const msgs = msg.payload.systems.map(s => ({
    url: s.url.replace(/\/gbfs$/, '/free_bike_status'),
    system: s.id
}));
// Zero tables (FN_GBFS_FF) of systems that left the list are dropped, so they
// neither grow on disk nor zero a returning system's old municipalities.
if (msgs.length && typeof flow.keys === 'function') {
    const aktiv = new Set(msgs.map(m => 'ffLast:' + String(m.system).replace(/[^A-Za-z0-9_-]+/g, '-')));
    for (const k of flow.keys()) if (k.startsWith('ffLast:') && !aktiv.has(k)) flow.set(k, undefined);
}
const statusText = msgs.length + ' Systeme';
node.status({ text: statusText });
// The per-system runs never see the complete inventory, so the free-floating
// summaries are pruned by age: every summary a system run produces is written
// in full (no change gate), so one not refreshed for 24 h (24 hourly runs) is
// no longer confirmed: the system left the list, or its vehicles are outside
// BW and were assigned to a border municipality before the strict lookup.
