        }
    } catch (e) { ok = null; }
} else if (typeof st === 'number' && st >= 200 && st < 300) ok = true;
const tables = {};
let kept = 0, dropped = 0;
for (const [key, field, value, id] of sc) {
    if (ok !== true && !(ok && ok.has(id))) { dropped++; continue; }
    const t = tables[key] = tables[key] || flow.get(key) || {};
    if (value === null) delete t[field]; else t[field] = value;
    kept++;
}
for (const key of Object.keys(tables)) flow.set(key, tables[key]);
if (dropped) {
    node.warn('Upsert not confirmed (' + st + '): ' + dropped + ' change signatures dropped, entities will be sent again'
              + (typeof msg.payload === 'string' ? ' — ' + msg.payload.slice(0, 200) : ''));
}
node.status({ fill: dropped ? 'yellow' : 'green', shape: 'dot', text: kept + ' committed' + (dropped ? ', ' + dropped + ' dropped' : '') + ' (' + st + ')' });
return msg;

// TRoE-Retention: Zeitreihen älter 12 Monate löschen (betrieb.md, Sprint 1.6)
// Nur attributes/subattributes (Volumentreiber); die kleine entities-Tabelle
// bleibt vollständig, damit Mintaka Entitäts-Metadaten rekonstruieren kann.
const { Client } = pg;
const client = new Client({
    host: env.get('TROE_DB_HOST') || 'timescale', port: 5432, database: 'orion',
    user: env.get('TROE_DB_USER') || 'udp', password: env.get('TROE_DB_PASSWORD'),
    application_name: 'udp-troe-retention',
    // Server-side limit, so an aborted client never leaves a query behind.
    connectionTimeoutMillis: 10000, statement_timeout: 1800000, query_timeout: 1900000,
});
await client.connect();
let a = 0, s = 0;
try {
    // ts-Indizes (idempotent): tragen Retention UND die 10-min-Statistikabfragen
    await client.query("CREATE INDEX IF NOT EXISTS attributes_ts_idx ON attributes (ts)");
    await client.query("CREATE INDEX IF NOT EXISTS subattributes_ts_idx ON subattributes (ts)");
    // (entityid, ts) mit text_pattern_ops: trägt Mintaka-Temporalabfragen je
    // Entität (vorher Seq-Scan über die ganze Tabelle) und die LIKE-Staffeln unten
    await client.query("CREATE INDEX IF NOT EXISTS attributes_entityid_ts_idx ON attributes (entityid text_pattern_ops, ts)");
    a = (await client.query("DELETE FROM attributes WHERE ts < (now() AT TIME ZONE 'utc') - interval '12 months'")).rowCount;
    s = (await client.query("DELETE FROM subattributes WHERE ts < (now() AT TIME ZONE 'utc') - interval '12 months'")).rowCount;

    // Gestaffelt: Einzelstandorte (Ladesäulen, Carsharing-Stationen,
    // Bürgersensoren) sind der Volumentreiber des landesweiten Stufe-3-Ausbaus,
    // werden aber nirgends über Monate ausgewertet — die Dashboards zeigen
    // ihren aktuellen Zustand auf der Karte. Aggregate je Gemeinde bleiben die
    // vollen 12 Monate, weil die Verlaufsdiagramme darauf beruhen.
    //
    // ParkingSite stand hier bis Sprint 2.9 mit drin, als der Konnektor noch
    // ~1,04 Mio Zeilen/Tag schrieb. Seit der Trennung von Stamm- und
    // Bewegungsdaten sind es grob 6.000 — die Staffel spart nichts mehr und
    // schadet sogar: Die statischen Attribute einer Anlage werden genau einmal
    // bei der Erstsichtung geschrieben und danach nie wieder. Ein Löschen nach
    // 3 Monaten entfernt damit die einzige Zeile, die es je gab, ohne dass sie
    // nachwächst. Der Broker bliebe korrekt (er hält den Ist-Stand), aber die
    // Temporal-API hätte für Parkanlagen dauerhaft nichts mehr zu liefern.
    const kurz = (await client.query(
        "DELETE FROM attributes WHERE ts < (now() AT TIME ZONE 'utc') - interval '3 months' " +
        "AND (entityid LIKE 'urn:ngsi-ld:EVChargingStation:%' " +
        "  OR entityid LIKE 'urn:ngsi-ld:CarSharingStation:%' " +
        "  OR entityid LIKE 'urn:ngsi-ld:AirQualityObserved:bw-sensor-%')")).rowCount;
    a += kurz;
    if (kurz) node.warn('Retention: ' + kurz + ' Zeilen aus Einzelstandorten (3-Monats-Staffel)');
    // Verwaiste Reste der abgelösten Reutlingen-Parkpipeline: OffStreetParking wird
    // nirgends mehr geschrieben, liegt aber noch im Temporal-Store (nicht im Broker).
    // Idempotent aufräumen — greift beim ersten Lauf, danach 0 Zeilen.
    const verwaist = (await client.query(
        "DELETE FROM attributes WHERE entityid LIKE 'urn:ngsi-ld:OffStreetParking:%'")).rowCount;
    if (verwaist) node.warn('Retention: ' + verwaist + ' verwaiste OffStreetParking-Zeilen entfernt');
    a += verwaist;

    // Alt-Schema-Reste von parken-bw: Bis Sprint 2.9 entstand die Entitäts-ID aus
    // dem geslugten Anlagennamen, seither aus dem ParkAPI-Schlüssel
    // (»parkapi-<id>«). Die alten Zeilen wachsen nicht nach — ihre Entitäten
    // werden nie wieder geschrieben —, altern seit dem Herausnehmen von
    // ParkingSite aus der 3-Monats-Staffel aber auch nicht mehr von selbst weg.
    // Auf dem Referenzcluster waren es 23,8 Mio Zeilen, 47 % der Tabelle.
    //
    // Die IDs kommen aus der KLEINEN entities-Tabelle (dort 101.000 Zeilen), nicht
    // aus einem LIKE über attributes: Ein »NOT LIKE« auf 22 GB lässt sich nicht
    // indizieren, der Planer wählt einen Seq Scan — und zwar auch dann noch jede
    // Nacht, wenn längst nichts mehr zu tun ist. Mit einer konkreten ID-Liste
    // greift attributes_entityid_ts_idx (Bitmap Index Scan, gemessen 57 k statt
    // 2,9 Mio geschätzte Kosten). Der Leerlauf kostet damit einen Scan über die
    // kleine Tabelle statt über die große.
    const altIds = (await client.query(
        "SELECT DISTINCT id FROM entities" +
        " WHERE (id LIKE 'urn:ngsi-ld:ParkingSite:%' AND id NOT LIKE 'urn:ngsi-ld:ParkingSite:parkapi-%')" +
        "    OR (id LIKE 'urn:ngsi-ld:BikeParking:%' AND id NOT LIKE 'urn:ngsi-ld:BikeParking:parkapi-%')"
        )).rows.map(r => r.id);
    // Stapelgröße klein halten: Auf dem Referenzcluster hingen rund 70.000 Zeilen
    // an EINER Anlage, fünf IDs je Anweisung sind also schon ~350.000 Zeilen.
    // Der Deckel begrenzt die Nacht; der Rest folgt in der nächsten (dort fünf
    // Nächte). Die entities-Zeilen bleiben stehen — sie sind klein, tragen die
    // Mintaka-Metadaten und machen diesen Schritt beim nächsten Lauf idempotent.
    const ALT_STAPEL = 5, ALT_DECKEL = 5000000;
    let altPark = 0, altIdx = 0;
    while (altIdx < altIds.length && altPark < ALT_DECKEL) {
        altPark += (await client.query("DELETE FROM attributes WHERE entityid = ANY($1::text[])",
                                       [altIds.slice(altIdx, altIdx + ALT_STAPEL)])).rowCount;
        altIdx += ALT_STAPEL;
    }
    if (altPark) node.warn('Retention: ' + altPark + ' Zeilen von ' + Math.min(altIdx, altIds.length)
                           + '/' + altIds.length + ' Parkanlagen im Alt-ID-Schema entfernt'
                           + (altPark >= ALT_DECKEL ? ' (Deckel erreicht, Rest folgt morgen)' : ''));
    a += altPark;

    // Totals per entity type for the 10-minute statistics (FN_TROE). This is
    // the ONLY full scan of attributes – once a night, after the deletes, so it
    // counts what actually remains. Replaced atomically: readers see either
    // yesterday's or today's figures, and vanished types disappear.
    await client.query("CREATE TABLE IF NOT EXISTS udp_troe_type_stats (" +
        "typ text PRIMARY KEY, n bigint NOT NULL, e bigint NOT NULL, computed_at timestamptz NOT NULL)");
    await client.query('BEGIN');
    try {
        await client.query("DELETE FROM udp_troe_type_stats");
        await client.query("INSERT INTO udp_troe_type_stats (typ, n, e, computed_at) " +
            "SELECT split_part(entityid, ':', 3), count(*), count(DISTINCT entityid), now() " +
            "FROM attributes GROUP BY 1");
        await client.query('COMMIT');
    } catch (err) {
        await client.query('ROLLBACK');
        throw err;
    }
} finally {
    await client.end();
}
node.status({ text: 'gelöscht: ' + a + ' attributes / ' + s + ' subattributes' });
msg.payload = { deletedAttributes: a, deletedSubattributes: s, at: new Date().toISOString() };
return msg;
